const retryItems=[];
for (const item of items) {
  const management=item.json.management||{};
  if (management.retryScheduled!==true || !management.retryRequest) continue;
  const delaySeconds=Math.max(1,Number(management.retryDelaySeconds||1));
  retryItems.push({json:{...item.json,readyRequest:management.retryRequest,retryCount:Number(management.retryCount||0),retryDelaySeconds:delaySeconds,retryQueueEntry:management.retryQueueEntry},pairedItem:item.pairedItem});
}
return retryItems;

const out=[];
for (const item of items) {
  const wb=item.json.management?.recipientStatusWriteback;
  if (!wb?.values?.Job_ID) continue;
  out.push({json:{...wb.values},pairedItem:item.pairedItem});
}
return out;

