const out=[];
for (const item of items) {
  const management=item.json.management||{};
  if (management.failoverScheduled!==true || !management.failoverRequest) continue;
  out.push({json:{...management.failoverRequest,retryCount:Number(management.retryCount||0)},pairedItem:item.pairedItem});
}
return out;

const emailRows=$items("Google Sheets - Email List").map((item)=>item.json||{});
const queueRows=$items("Google Sheets - Retry Queue Input").map((item)=>item.json||{});
const accountRows=items.map((item)=>item.json||{});
const queueByJob=new Map(queueRows.filter((row)=>row.Job_ID).map((row)=>[String(row.Job_ID),row]));
const accountReportSeeds={};
for (const row of accountRows) {
  const campaign=String(row.Campaign_ID||'default-campaign'); const profile=String(row.Profile_ID||'');
  if (!profile) continue;
  accountReportSeeds[campaign]=accountReportSeeds[campaign]||{}; accountReportSeeds[campaign][profile]={...row};
}
const terminal=new Set(['SENT','QUEUED','FAILED','MANUAL_REVIEW','DUPLICATE','BLOCKED']);
const parseObject=(value)=>{ if (!value) return {}; if (typeof value==='object') return value; try { const parsed=JSON.parse(String(value)); return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:{}; } catch { return {}; } };
const parseArray=(value)=>{ if (Array.isArray(value)) return value.map(String).filter(Boolean); if (!value) return []; try { const parsed=JSON.parse(String(value)); return Array.isArray(parsed)?parsed.map(String).filter(Boolean):[]; } catch { return String(value).split(',').map((v)=>v.trim()).filter(Boolean); } };
const now=Date.now();
const out=[];
for (const row of emailRows) {
  const status=String(row.status||row.Status||'').trim().toUpperCase();
  if (terminal.has(status)) continue;
  const jobId=String(row.Job_ID||'').trim();
  const campaignId=String(row.Campaign_ID||'default-campaign').trim()||'default-campaign';
  const accountReportSeed=accountReportSeeds[campaignId]||{};
  const queue=jobId?queueByJob.get(jobId):undefined;
  const queueStatus=String(queue?.Queue_Status||'').trim().toUpperCase();
  if (queueStatus==='COMPLETED'||queueStatus==='MANUAL_REVIEW'||queueStatus==='FAILED_FINAL') continue;
  const nextRetryAt=Date.parse(String(queue?.Next_Retry_At||''));
  if (queueStatus==='RETRY_WAIT'&&Number.isFinite(nextRetryAt)&&nextRetryAt>now) continue;
  const checkpoint=parseObject(queue?.Lifecycle_Checkpoint);
  const resumeStage=String(queue?.Resume_Stage||'').trim();
  const providerInvoiceId=String(queue?.Provider_Invoice_ID||'').trim();
  const currentProfileId=String(queue?.Current_Profile_ID||'').trim();
  const sideEffectStage=String(queue?.Side_Effect_Stage||checkpoint.postStatus&&'invoice.created'||(providerInvoiceId?'invoice.created':'none'));
  const requiredProfileId=String(queue?.Required_Profile_ID||(queueStatus==='RETRY_WAIT'?currentProfileId:'')).trim();
  const failoverState={
    schemaVersion:'1.0', failoverGroup:String(queue?.Failover_Group||''), originalProfileId:String(queue?.Original_Profile_ID||currentProfileId),
    currentProfileId, attemptedProfileIds:parseArray(queue?.Attempted_Profile_IDs), failoverCount:Number(queue?.Failover_Count||0),
    requiredProfileId:queueStatus==='FAILOVER_READY'?'':requiredProfileId, queueStatus, sideEffectStage,
  };
  const lifecycleResume=resumeStage&&providerInvoiceId?{
    schemaVersion:'1.0', source:'status-manager', approved:true, stage:resumeStage,
    profileId:currentProfileId, providerInvoiceId, checkpoint,
  }:null;
  out.push({json:{...row,invoiceRouterState:{retryCount:Number(queue?.Retry_Count||0),failoverState,lifecycleResume,accountReportSeed}},pairedItem:{item:out.length}});
}
return out;

return items.flatMap((item)=>{
  const recipient=item.json.recipient||{}; const job=item.json.job||{};
  if (!job.jobId) return [];
  return [{json:{Email:recipient.email||'',status:'PROCESSING',Name:recipient.name||'',Address:recipient.address||'',Job_ID:job.jobId,Campaign_ID:job.campaignId||'',Attempt_Count:Number(job.attemptCount||0),Last_Account:job.lastAccountId||'',Last_Error:'',Updated_At:new Date().toISOString()},pairedItem:item.pairedItem}];
});
